async function killOne(pattern, timeoutMs = 25000) {
  const start = Date.now();
  while (Date.now() - start < timeoutMs) {
    const st = sdk.getState();
    const npc = st?.nearbyNpcs
      ?.filter((n:any) => new RegExp(pattern,'i').test(n.name))
      ?.filter((n:any) => n.optionsWithIndex?.some((o:any)=>/attack/i.test(o.text)))
      ?.sort((a:any,b:any)=>a.distance-b.distance)[0];
    if (!npc) { await sdk.waitForTicks(2); continue; }
    console.log('target', npc.name, npc.combatLevel, npc.distance);
    try { await bot.attack(npc); } catch(e) { console.log('atk err', String(e).slice(0,80)); }
    // wait for it to die
    const t0 = Date.now();
    while (Date.now() - t0 < timeoutMs) {
      await sdk.waitForTicks(3);
      const s2 = sdk.getState();
      const still = s2?.nearbyNpcs?.some((n:any)=>n.index===npc.index && n.hitpoints?.current>0);
      if (!s2?.player?.combat?.inCombat && still === false) { console.log('killed', npc.name); return true; }
      if (still === false) { console.log('gone', npc.name); return true; }
      if (!s2?.player?.combat?.inCombat && Date.now()-t0>4000) { console.log('lost target', npc.name); break; }
    }
  }
  return false;
}

